import{_ as t,l as n,o as e,c as l,v as r,p as E,x as i,d as s,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"莫迪利亚尼–米勒","description":"","frontmatter":{"title":"莫迪利亚尼–米勒","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/modigliani-miller.md","filePath":"econ/modigliani-miller.md","lastUpdated":1789023840000}'),d={name:"econ/modigliani-miller.md"};function _(c,a,h,m,B,D){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="莫迪利亚尼–米勒" tabindex="-1">莫迪利亚尼–米勒 <a class="header-anchor" href="#莫迪利亚尼–米勒" aria-label="Permalink to &quot;莫迪利亚尼–米勒&quot;">​</a></h1><div class="epigraph"><p>在无摩擦市场上，企业的总价值由资产的收益流决定，与把该收益流切成债还是股无关。</p><footer>—— Modigliani and Miller, The Cost of Capital, Corporation Finance and the Theory of Investment, American Economic Review 1958</footer></div><p><a href="/econ/shadow-banking">上一课</a>（影子银行）。<a href="/econ/basel-capital">资本监管与巴塞尔</a>。监管把银行股本写成稀缺约束，好像股权「贵」、存款「便宜」。本课缺口是先给出无摩擦基准：若市场完全，资本结构不改变总价值，贵的不是股，是资产风险。后课的税、破产、信息不对称都是对这一基准的偏离。公司金融从这里开始，不再写准备金。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课把资本比率当成硬约束，容易滑向「股本成本高于债务成本，所以银行应当尽量少持有股本」。若这句话成立，任意企业都应当把杠杆加到极限。Modigliani 与 Miller（1958）指出：这句话把<strong>负债的要求回报</strong>和<strong>加权平均资本成本</strong>搅在一起。债务要求回报低，是因为它先于股权受偿、风险更小；多借债会把剩余股权变得更险，股权要求回报上升。两边加总，对企业资产的要求回报可以不变。</p><p>缺口因此不是估计某个行业的「最优负债率」，而是：在哪一组假设下，切片方式不改变饼的大小。没有这组假设，后课的权衡与优序没有对照系。</p><p><span class="marginnote">命题 I：杠杆企业与无杠杆企业总价值相等。命题 II：股权成本随杠杆线性上升，正好抵消便宜债务的权重。两者是同一套利的两种写法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>1958 年的论证是套利，不是问卷调查。考虑两家企业，资产收益流相同，一家全股权，一家有债。若杠杆企业总价值更高，投资者可以卖掉杠杆企业的股票、按同一比例自行借贷去买无杠杆企业，复制收益并套出差额；反向亦可。家庭能自制杠杆，企业杠杆就没有溢价。这要求：无交易成本、无税收（或税对债与股对称）、无破产成本、信息对称、个人与企业借贷利率相同。</p><p>用符号：资产要求回报 \\(r_A\\) 由资产风险决定；债务 \\(r_D\\)、股权 \\(r_E\\)，杠杆 \\(D/E\\)。命题 II 是</p> \\[r_E = r_A + \\frac{D}{E}(r_A - r_D). \\]<p>加权平均 \\(r_A = \\frac{E}{E+D}r_E + \\frac{D}{E+D}r_D\\) 不随 \\(D/E\\) 变。巴塞尔若只是把 \\(D\\) 换成存款、\\(E\\) 换成普通股，无摩擦时提高 \\(E\\) 并不提高 \\(r_A\\)——提高的是更安全的股权、更少的存款风险。</p>',12)),(e(),E(A,null,{default:i(()=>[p(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASSET%5B%22%E8%B5%84%E4%BA%A7%E6%94%B6%E7%9B%8A%E6%B5%81%22%5D%20--%3E%20VA%5B%22%E6%80%BB%E4%BB%B7%E5%80%BC%20VA%22%5D%0A%20%20VA%20--%3E%20E%5B%22%E8%82%A1%E6%9D%83%E8%A6%81%E6%B1%82%E5%9B%9E%E6%8A%A5%E4%B8%8A%E5%8D%87%22%5D%0A%20%20VA%20--%3E%20D%5B%22%E5%80%BA%E5%8A%A1%E8%A6%81%E6%B1%82%E5%9B%9E%E6%8A%A5%E8%BE%83%E4%BD%8E%22%5D%0A%20%20HOME%5B%22%E5%AE%B6%E5%BA%AD%E8%87%AA%E5%88%B6%E6%9D%A0%E6%9D%86%22%5D%20--%3E%20ARB%5B%22%E5%A5%97%E5%88%A9%3A%20%E5%88%87%E7%89%87%E6%97%A0%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20ARB%20--%3E%20VA%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>MM 不否认 \\(r_E \\gt r_D\\)。它否认的是「因此应当用债务替换股权来降低资金成本」。资金成本是 \\(r_A\\)，不是 \\(r_E\\) 或 \\(r_D\\) 单独。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是市场替代企业的资产负债表。完全市场上，投资者能复制任何切片；企业多发行一单位债、少发行一单位股，只是把同一状态依存现金流在投资者之间重切。<a href="/econ/state-contingent">或有要求权</a>语言下，这是 Modigliani–Miller 与 Arrow–Debreu 的交汇：证券结构不扩张可行集时，价格只取决于状态的影子价格，不取决于哪家企业发行哪种券。</p><p>银行应用的刺耳之处在此。若存款因为保险和支付服务而<strong>不是</strong>普通债务——它带流动性服务、受担保——则家庭不能无成本地自制「银行存款」，MM 的复制破了。本课先把破口标出来，不在这里写存款保险溢价；权衡课写税收与破产，优序课写信息。监管把股权当成贵的，等于已经站在摩擦世界；先要承认基准。</p><h3 id="命题-ii-不是「股权更贵所以少发股」" tabindex="-1">命题 II 不是「股权更贵所以少发股」 <a class="header-anchor" href="#命题-ii-不是「股权更贵所以少发股」" aria-label="Permalink to &quot;命题 II 不是「股权更贵所以少发股」&quot;">​</a></h3><p>实务语言常说股权成本 12%、债务成本 4%，因此应当借债。命题 II 说：12% 已经包含杠杆；再借债，12% 会变成更高的数，加权仍是 \\(r_A\\)。正确的比较是项目的 \\(r_A\\) 对资产风险，不是拿 \\(r_E\\) 与 \\(r_D\\) 比大小。加权平均资本成本（WACC）在无摩擦时不随 \\(D/E\\) 变，正是命题 I 的对偶。后课一旦引入税盾，WACC 会随杠杆下降——那是摩擦，必须单独声明。</p><p><span class="marginnote">套利要求个人能按与企业相同的利率借贷。若家庭借贷更贵，企业代为加杠杆可以有溢价，无关性失败。这是另一种摩擦，本课不展开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>1958 年论文没有公司所得税；1963 年的更正引入税盾，那是下一课的第一块摩擦，不是本课的结论。也不要把 MM 读成「资本结构在现实中无关」：它是无关性定理，用来定位有关性从哪来。实证里的负债率分布、评级门槛，全部是对假设的违反，不是对套利逻辑的否证。</p><p>本课不估计 beta，不写 CAPM 的均衡溢价——那是<a href="/econ/capm-theory">作为均衡的 CAPM</a>。\\(r_A\\) 在这里只是资产风险的占位符。股利政策的无关性是 1961 年另一篇，放到<a href="/econ/dividend-fcf">股利</a>。</p><p>也不要把 1958 年论文读成「债务无风险」。命题允许 \\(r_D\\) 随杠杆上升，只要上升被 \\(r_E\\) 的进一步上升所匹配、且没有破产的资源损耗。破产一旦消耗真资源，就离开本课，进入权衡。</p><p>后课默认：无摩擦时 \\(V\\) 与切片无关，\\(r_A\\) 才是资金成本。税盾、破产、柠檬、代理，都是对复制条件的放松，必须单独点名。不要用「股权成本高于债务成本」当作已经否证命题 I。</p><p>命题 II 允许 \\(r_E\\gt r_D\\)。它否认的是因此应当用债替换股来降低 WACC。</p><p>家庭不能自制公司税盾，也不能自制破产法。复制从下一课开始失败。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无摩擦时总价值由资产决定，与债股切片无关。</li><li>股权成本随杠杆上升，抵消「便宜」债务；加权成本是资产成本。</li><li>银行股本显得贵，说明保险、税或信息已破坏复制。</li><li>出处：Modigliani and Miller, <em>AER</em> 1958。</li></ul>',16))])}const g=t(d,[["render",_]]);export{u as __pageData,g as default};
